public void AVAinitFromNiedaxSalesParameter()
{
    AVASalesParameters              salesParameters = AVASalesParameters::find();
    this.KCS_QLStdStepSize          = salesParameters.PositionIncrement;
    this.KCS_ShowIntPosPrice        = NoYes::Yes;
    this.KCS_QuotationShorttext     = NoYes::Yes;
    this.KCS_StatusId               = salesParameters.StatusId;
    this.KCS_DataArea               = curExt(); 
}

/// <summary>
/// designed from AVA
/// </summary>
/// <returns>container</returns>
public container  AVAcalcExchRate()
{
    AVASalesParameters          avaSalesParameters    = AVASalesParameters::find();
    SalesParameters             salesParameters       = SalesParameters::find();
    ExchangeRateCalculation     exchangeRateCalculation,  exchangeRateCalculationLimitPrice;

    if (this.CurrencyCode != salesParameters.GenericCurrency)
    {
        exchangeRateCalculation = ExchangeRateCalculation::newExchangeDate(salesParameters.ExchangeRateType,
                                                                                                       salesParameters.GenericCurrency,
                                                                                                       this.CurrencyCode,
                                                                                                       this.AVAExchangeRateDate);
        exchangeRateCalculationLimitPrice = ExchangeRateCalculation::newExchangeDate(avaSalesParameters.LimitPriceExchRateType,
                                                                                                                salesParameters.GenericCurrency,
                                                                                                                this.CurrencyCode,
                                                                                                                this.AVAExchangeRateDate);
    }

    return [exchangeRateCalculation ? exchangeRateCalculation.getExchangeRate1() : 0, exchangeRateCalculationLimitPrice ?  exchangeRateCalculationLimitPrice.getExchangeRate1() : 0];

}

