/// <summary>
/// designed by AVANADE
/// </summary>
/// <returns>boolean</returns>
public boolean AVAExistPositions()
{
    SalesQuotationLine sql;
    boolean ret;

    select firstonly RecId from sql where sql.QuotationId == this.QuotationId && sql.RecId;
    ret = sql.RecId;

    return ret;
}

/// <summary>
/// designed frm AVA
/// </summary>
/// <returns>boolean</returns>
public boolean avaIsClosed()
{
    boolean ret;

    if(     this.QuotationStatus == SalesQuotationStatus::Confirmed
        ||  this.QuotationStatus == SalesQuotationStatus::Cancelled
        ||  this.QuotationStatus == SalesQuotationStatus::Lost)
    {
        ret = true;
    }

    return ret;
}

