/// <summary>
///     AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///     <c>FieldId</c> as type
/// </param>
/// <param name="_userInput">
///     <c>boolean</c> as type
/// </param>
public void modifiedField(  FieldId _fieldId,
                            boolean _userInput  )
{ 
    KCS_KBVRequestTable         locKCS_KBVRequestTable;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    next modifiedField(_fieldId, _userInput);

    switch (_fieldId)
    {
        case fieldNum(SalesQuotationTable, CustAccount):
            this.avaCustAccountChanged();
            break;

        case fieldNum(SalesQuotationTable, KCS_KBVBuildingProjectId) :
            locKCS_KBVBuildingProjectTable  = KCS_KBVBuildingProjectTable::find(this.KCS_KBVBuildingProjectID);
            this.KCS_KBVSubject             = locKCS_KBVBuildingProjectTable.KCS_KBVSubject;
            this.KCS_KBVRequestId           = '';
            break;

        case fieldNum(SalesQuotationTable, KCS_KBVRequestId) :
            locKCS_KBVRequestTable          = KCS_KBVRequestTable::find(this.KCS_KBVRequestId);
            locKCS_KBVBuildingProjectTable  = KCS_KBVBuildingProjectTable::find(locKCS_KBVRequestTable.KCS_KBVBuildingProjectID);
            this.KCS_KBVBuildingProjectID   = locKCS_KBVRequestTable.KCS_KBVBuildingProjectID;
            this.KCS_KBVSubject             = locKCS_KBVBuildingProjectTable.KCS_KBVSubject;
            break;

        case fieldNum(SalesQuotationTable, WorkerSalesTaker) :
            locKCS_KBVRequestTable          = KCS_KBVRequestTable::find(this.KCS_KBVRequestId);
            if(locKCS_KBVRequestTable.RecId)
            {
                ttsbegin;
                locKCS_KBVRequestTable.selectForUpdate(true);
                locKCS_KBVRequestTable.KCS_KBVModifiedBy = this.WorkerSalesTaker;
                //locKCS_KBVRequestTable.KCS_KBVModifiedDate  = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
                if(!locKCS_KBVRequestTable.AVAWorkerSalesTaker)
                {
                    locKCS_KBVRequestTable.AVAWorkerSalesTaker = this.WorkerSalesTaker;
                }
                locKCS_KBVRequestTable.update();
                ttscommit;
            }
            break;

        default : 
            break;
    }
}

/// <summary>
/// logic for when the CustAccount has been modified
/// </summary>
public void avaCustAccountChanged()
{
    this.avaUpdateHeaderAccountChanged();
}

/// <summary>
/// update Header fields for new CustAccount Id
/// </summary>
public void avaUpdateHeaderAccountChanged()
{
    CustTable           avaCustTable    = CustTable::find(this.CustAccount);
    smmBusRelChainGroup smmBusRelChainGroup;

    select firstonly  smmBusRelChainGroup
            where smmBusRelChainGroup.ChainId == avaCustTable.CompanyChainId;

    this.InvoiceAccount             = this.CustAccount;
    this.ContactPersonId            = '';
    this.Email                      = '';
    this.AVACBSCommissSalesGroup    = avaCustTable.SalesGroup;
    this.SalesUnitId                = avaCustTable.SalesDistrictId;
    this.WorkerSalesResponsible     = avaCustTable.MainContactWorker;
    this.KCS_CustCity               = avaCustTable.postalAddress().City;

    this.PriceGroupId               = avaCustTable.PriceGroup   ?    avaCustTable.PriceGroup    :  smmBusRelChainGroup.AVAPriceGroupId;
    this.AVANetPG1                  = avaCustTable.AVANetPG1    ?    avaCustTable.AVANetPG1     :  smmBusRelChainGroup.AVANetPG1;
    this.AVANetPG2                  = avaCustTable.AVANetPG2    ?    avaCustTable.AVANetPG2     :  smmBusRelChainGroup.AVANetPG2;
    this.LineDisc                   = avaCustTable.LineDisc     ?    avaCustTable.LineDisc      :  smmBusRelChainGroup.AVALineDisc;
    this.KCS_ChainLineDiscCode      = smmBusRelChainGroup.AVALineDisc;
    this.DlvTerm                    = avaCustTable.DlvTerm      ?    avaCustTable.DlvTerm       :  smmBusRelChainGroup.AVADlvTerm;
    this.DlvMode                    = avaCustTable.DlvMode      ?    avaCustTable.DlvMode       :  smmBusRelChainGroup.AVADlvMode;
    this.Payment                    = avaCustTable.PaymMode     ?    avaCustTable.PaymMode      :  smmBusRelChainGroup.AVAPayment;
    this.CashDisc                   = avaCustTable.CashDisc     ?    avaCustTable.CashDisc      :  smmBusRelChainGroup.AVACashDisc;
    this.KCS_MaxBonusAmount         = avaCustTable.KCS_MaxBonusAmount != 0   ?    avaCustTable.KCS_MaxBonusAmount   :  smmBusRelChainGroup.AVAMaxBonusAmount;
}

