/// <summary>
/// designed from AVA FRN
/// </summary>
public void AVAKBVRequestTableStatusUpdate()
{
    KCS_KBVRequestTable     requestTable = KCS_KBVRequestTable::find(this.KCS_KBVRequestId);
    SalesQuotationTable     locSalesQuotationTable;


    if (requestTable.RecId)
    {
        if ((this.QuotationStatus == SalesQuotationStatus::Sent
          || this.QuotationStatus == SalesQuotationStatus::Confirmed
          || this.QuotationStatus == SalesQuotationStatus::Lost)
             && requestTable.KCS_KBVRequestStatus != KCS_KBVRequestStatus::Answered)
        {
            select firstonly RecId, CreatedBy, CreatedDateTime from locSalesQuotationTable
                where locSalesQuotationTable.KCS_KBVRequestId == requestTable.KCS_KBVRequestID
                && locSalesQuotationTable.QuotationStatus    == SalesQuotationStatus::Created;

            if (!locSalesQuotationTable.RecId )
            {
                requestTable.KCS_KBVRequestStatus = KCS_KBVRequestStatus::Answered;

            }

        }
        ttsbegin;
        requestTable.selectForUpdate(true);
        requestTable.update();
        ttscommit;
    }

}

/// <summary>
/// designed from AVA
/// </summary>
public void AVAKBVRequestTableUpdate()
{

    // SalesQuotationTable     helpSalesQuotationTable = SalesQuotationTable::findRec(this.RecId);
    // TransDate               t = DateTimeUtil::date(helpSalesQuotationTable.CreatedDateTime);
    // UserId                  u = helpSalesQuotationTable.createdBy;
    KCS_KBVRequestTable     requestTable;
    HcmWorkerRecId          locHcmWorkerRecId;
    AVAWorkerSalesTaker     locAVAWorkerSalesTakerUpdated;
    SalesQuotationTable     locSalesQuotationTable;

    requestTable = KCS_KBVRequestTable::find(this.KCS_KBVRequestId);

    if (requestTable)
    {
        requestTable.KCS_KBVRequestStatus   = KCS_KBVRequestStatus::InProcess;
        if (this.QuotationStatus == SalesQuotationStatus::Sent || this.QuotationStatus == SalesQuotationStatus::Lost || this.QuotationStatus == SalesQuotationStatus::Confirmed)
        {
            select firstonly RecId, CreatedBy, CreatedDateTime from locSalesQuotationTable
                where locSalesQuotationTable.KCS_KBVRequestId == requestTable.KCS_KBVRequestID
                && locSalesQuotationTable.QuotationStatus    == SalesQuotationStatus::Created;
            if (!locSalesQuotationTable.RecId)
            {
                requestTable.KCS_KBVRequestStatus = KCS_KBVRequestStatus::Answered;
            }
        }   

        requestTable.LastQuotationId        = this.QuotationId;
        requestTable.KCS_KBVModifiedBy      = HcmWorker::userId2Worker(this.CreatedBy);
        requestTable.KCS_KBVModifiedDate    = DateTimeUtil::date(this.CreatedDateTime);

        if (requestTable.AVAWorkerSalesTaker == 0 && this.WorkerSalesTaker != 0)
        {
            requestTable.AVAWorkerSalesTaker    = this.WorkerSalesTaker;
            locAVAWorkerSalesTakerUpdated       = true;
        }

        ttsbegin;
        requestTable.selectForUpdate(true);
        requestTable.update();

        if(requestTable.AVAWorkerSalesTaker == 0)
        {
            locHcmWorkerRecId = HcmWorkerLookup::currentWorker();
            if(locHcmWorkerRecId)
            {
                requestTable.assignUnassignRequest(locHcmWorkerRecId);
                requestTable.assignUnassignRelatedRequests(locHcmWorkerRecId);
            }
        }
        else if(locAVAWorkerSalesTakerUpdated)
        {
            locHcmWorkerRecId = this.WorkerSalesTaker;
            if(locHcmWorkerRecId)
            {
                requestTable.assignUnassignRequest(locHcmWorkerRecId);
                requestTable.assignUnassignRelatedRequests(locHcmWorkerRecId);
            }
        }
        ttscommit;
    }
}

/// <summary>
/// defined from AVA FRN
/// </summary>
public void AVAKBVRequestTablePostUpdate()
{
    HcmWorkerRecId          locHcmWorkerRecId;
    LogisticsPostalAddress  address;
    KCS_KBVRequestTable     requestTable;
    AVAWorkerSalesTaker     locAVAWorkerSalesTakerUpdated;

    requestTable = KCS_KBVRequestTable::find(this.KCS_KBVRequestId);

    if (requestTable)
    {
        if (requestTable.AddressCountryRegionId == '')
        {
            if (requestTable.AVAWorkerSalesTaker == 0 && this.WorkerSalesTaker != 0)
            {
                requestTable.AVAWorkerSalesTaker    = this.WorkerSalesTaker;
                locAVAWorkerSalesTakerUpdated       = true;
            }
            address = this.deliveryAddress();

            requestTable.AddressCountryRegionId = address.CountryRegionId;
            requestTable.AddressStreet          = address.Street;
            requestTable.AddressCity            = address.City;
            requestTable.AddressZipCodeId       = address.ZipCode;
            requestTable.SalesGroup             = this.SalesGroup;
            requestTable.SalesUnitId            = this.SalesUnitId;

            ttsbegin;
            requestTable.selectForUpdate(true);
            requestTable.update();

            if(requestTable.AVAWorkerSalesTaker == 0)
            {
                locHcmWorkerRecId = HcmWorkerLookup::currentWorker();
                if(locHcmWorkerRecId)
                {
                    requestTable.assignUnassignRequest(locHcmWorkerRecId);
                    requestTable.assignUnassignRelatedRequests(locHcmWorkerRecId);
                }
            }
            else if(locAVAWorkerSalesTakerUpdated)
            {
                locHcmWorkerRecId = this.WorkerSalesTaker;
                if(locHcmWorkerRecId)
                {
                    requestTable.assignUnassignRequest(locHcmWorkerRecId);
                    requestTable.assignUnassignRelatedRequests(locHcmWorkerRecId);
                }
            }
            ttscommit;

            KCS_KBVBPCompanySpecific        companySpecific = KCS_KBVBPCompanySpecific::find(requestTable.KCS_KBVBuildingProjectID);
            if (companySpecific.RecId && companySpecific.KCS_KBVCompSpecCountryId == '')
            {
                companySpecific.smmSalesUnitId              = this.SalesUnitId;
                companySpecific.CommissSalesGroup           = this.SalesGroup;
                companySpecific.KCS_KBVMainResponsible      = this.WorkerSalesResponsible;
                companySpecific.KCS_KBVSmmSalesUnitIndoor   = this.KCS_KBVSmmSalesUnitIndoor;
                companySpecific.KCS_KBVCompSpecZipCode      = address.ZipCode;
                companySpecific.KCS_KBVCompSpecCountryId    = address.CountryRegionId;
                ttsbegin;
                companySpecific.selectForUpdate(true);
                companySpecific.update();
                ttscommit;
            }
        }
    }
}

