/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_this">SalesQuotationTable</param>
/// <returns>TransDate</returns>
[SysClientCacheDataMethodAttribute(true)]
public static display TransDate AVADisplayLastSendDate(SalesQuotationTable  _this)
{
    TransDate               lastSendDate;
    CustQuotationJour       custQuotationJour;
    CustQuotationSalesLink  custQuotationSalesLink;

    select firstonly QuotationDate, RecId from custQuotationJour
        order by  QuotationDate  DESC
        join custQuotationSalesLink
            where custQuotationSalesLink.quotationId == custQuotationJour.QuotationId
               && custQuotationSalesLink.origQuotationId == _this.QuotationId; 
    lastSendDate = custQuotationJour.QuotationDate;

    return lastSendDate;

}

