/// <summary>
/// designed by AVANADE WEN
/// </summary>
/// <param name = "_salesQuotationTable">SalesQuotationTable</param>
public void initFromSalesQuotationTable(SalesQuotationTable      _salesQuotationTable)
{
    next initFromSalesQuotationTable(_salesQuotationTable);

    DocuRef docuRef;

    this.KCS_RefQuotationId     = _salesQuotationTable.KCS_RefQuotationId;
    this.KCS_GAEBImportID       = _salesQuotationTable.KCS_GAEBImportID;
    this.KCS_OrgQuotationId     = _salesQuotationTable.QuotationId;
    this.KCS_QLStdStepSize      = _salesQuotationTable.KCS_QLStdStepSize;
    this.KCS_QuotationShorttext = _salesQuotationTable.KCS_QuotationShorttext;
    this.AVANoExpiryOverrun     = _salesQuotationTable.AVANoExpiryOverrun;

    if (this.RecId)
    {
        KCS_HDMSalesQuotationTableInfoFields::copyQuotInfoField(_salesQuotationTable, this);
        AVASpecialDiscQuotation::copyFromSpecialDiscQoutation(this.QuotationId, AVASpecialDiscQuotation::find(_salesQuotationTable.QuotationId));
        while select docuRef where docuRef.RefTableId == tableNum(SalesQuotationTable)
                            && docuRef.RefRecId == _salesQuotationTable.RecId
        {
            DocuRef::createFromDocuRef(docuRef, this.RecId, tableNum(SalesQuotationTable));
        }
    }
}

/// <summary>
/// designed by AVANADE WEN
/// </summary>
/// <param name = "_custQuotationJour">CustQuotationJour</param>
public void initFromCustQuotationJour(CustQuotationJour _custQuotationJour)
{
    next initFromCustQuotationJour(_custQuotationJour);

    DocuRef docuRef;

    this.KCS_RefQuotationId     = _custQuotationJour.salesQuotationTable().KCS_RefQuotationId;
    this.KCS_GAEBImportID       = _custQuotationJour.salesQuotationTable().KCS_GAEBImportID;
    this.KCS_OrgQuotationId     = _custQuotationJour.KCS_QuotationId;
    this.KCS_QLStdStepSize      = _custQuotationJour.salesQuotationTable().KCS_QLStdStepSize;
    this.KCS_QuotationShorttext = _custQuotationJour.salesQuotationTable().KCS_QuotationShorttext;
    this.AVANoExpiryOverrun     = _custQuotationJour.AVANoExpiryOverrun;
    this.QuotationExpiryDate    = _custQuotationJour.AVAQuotationExpiryDate;
    this.KCS_PriceDate          = _custQuotationJour.AVAPriceDate;

    if (this.RecId)
    {
        KCS_HDMSalesQuotationTableInfoFields::copyQuotInfoField(_custQuotationJour.salesQuotationTable(), this);
        AVASpecialDiscQuotationJour specialDiscQuotationJour;
        select firstonly specialDiscQuotationJour where specialDiscQuotationJour.QuotationJourRefRecId == _custQuotationJour.RecId;
        AVASpecialDiscQuotation::copyFromSpecialDiscQoutationJour(this.QuotationId, specialDiscQuotationJour);
        while select docuRef where docuRef.RefTableId == tableNum(CustQuotationJour)
                        && docuRef.RefRecId == _custQuotationJour.RecId
        {
            docuRef::createFromDocuRef(docuRef, this.RecId, tableNum(SalesQuotationTable));
        }
    }
}

