/// <summary>
/// AVA
/// </summary>
/// <param name = "_quotationId">SalesQuotationId</param>
public static void AVASetQuotNotPosted(SalesQuotationId    _quotationId)
{
    SalesQuotationTable sqt = SalesQuotationTable::find(_quotationId,true);
    if (sqt.RecId)
    {
        ttsbegin;
        sqt.AVAPosted = false;
        sqt.AVAPostedEnum = AVAPostedEnum::NotPosted;
        sqt.doUpdate();
        ttscommit;
    }

}

/// <summary>
///    AVA <c>validateDelete</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
boolean  validateDelete()
{
    boolean     ok;

    ok = next validateDelete();

    if (ok)
    {
        if(SalesQuotationLine::exist(this.QuotationId))
        {
            ok = false;
            warning("@NDX:NXAExistingPosPreventDeletion");
        }
    }
    return ok;
}

