/// <summary>
///    AVA <c>displayAVABaseAmount</c> method.
/// </summary>
/// <returns>
///    <c>Email</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display Amount displayAVABaseAmount()
{
    Amount              retVal;

    SalesQuotationLine locSalesQuotationLine;

    select sum(KCS_QLLVAmount)
    from    locSalesQuotationLine
    where   locSalesQuotationLine.QuotationId               == this.QuotationId
        &&  locSalesQuotationLine.KCS_CRMIsAlternativeLine  == NoYes::No
        &&  locSalesQuotationLine.KCS_QLInternalPosition    == 1;

    retVal = decRound(locSalesQuotationLine.KCS_QLLVAmount, 2);

    select sum(LineAmount)
    from    locSalesQuotationLine
    where   locSalesQuotationLine.QuotationId               == this.QuotationId
        &&  locSalesQuotationLine.KCS_CRMIsAlternativeLine  == NoYes::No
        &&  locSalesQuotationLine.KCS_QLInternalPosition    == 0;

    retVal += decround(locSalesQuotationLine.LineAmount, 2);

    return retVal;
}

/// <summary>
///    AVA <c>displayAVASpecialDiscAmount</c> method.
///     AVA - Schneider 30.04.2024
/// </summary>
/// <returns>
///    <c>Amount</c> as return value
/// </returns>
public Amount avaSpecialDiscAmount()
{
    Amount                      retVal;
    Amount                      locTmpAmount;
    Amount                      locBaseAmount;
    AVASpecialDiscQuotation locAVASpecialDiscQuotation;

    locAVASpecialDiscQuotation = AVASpecialDiscQuotation::find(this.QuotationId);

    if(locAVASpecialDiscQuotation.RecId)
    {
        locBaseAmount   = this.displayAVABaseAmount();
        retVal          = locBaseAmount;

        locTmpAmount    = decround((locBaseAmount * locAVASpecialDiscQuotation.SpecialDiscountPct1 / 100), 2);
        locBaseAmount   = locBaseAmount - locTmpAmount;
        locTmpAmount    = decround((locBaseAmount * locAVASpecialDiscQuotation.SpecialDiscountPct2 / 100), 2);
        locBaseAmount   = locBaseAmount - locTmpAmount;
        locTmpAmount    = decround((locBaseAmount * locAVASpecialDiscQuotation.SpecialDiscountPct3 / 100), 2);
        locBaseAmount   = locBaseAmount - locTmpAmount;

        retVal          = retVal - locBaseAmount;
    }
    else
    {
        retVal = 0.0;
    }

    return retVal;
}
